#!/usr/bin/env bash
# Генерирует internal/httpapi/unimplemented.gen.go: заглушки 501 для всех
# операций StrictServerInterface. Запускается из make gen-api.
set -euo pipefail
cd "$(dirname "$0")/../internal/httpapi"
{
cat <<'HDR'
// Code generated by scripts/gen-unimplemented.sh; DO NOT EDIT.

package httpapi

import "context"

// Unimplemented is available for test doubles and partial adapters.
// Production Server implements the full interface without embedding this type.
type Unimplemented struct{}
HDR
awk '/^type StrictServerInterface interface/{f=1;next} f&&/^}/{f=0} f&&/^\t[A-Z]/{sub(/^\t/,""); print "\nfunc (Unimplemented) " $0 " {\n\treturn nil, ErrNotImplemented\n}"}' api.gen.go
} > unimplemented.gen.go
gofmt -w unimplemented.gen.go
